; ------------------------------------------------------------------------------------------------ the FONY film (runs in the overlay bank, entry 4009h)
; A window of 128 x 72 pixels in SCREEN 2 with the sound in one stream (tools/fony_video.py): the players are generated by tools/gen_fony.py (PSG: fony.inc, w_fony in fonyw.inc for a
; machine with a VDP wait state) and tools/gen_fony16.py (SCC: fony16.inc, w_fony16 in fony16w.inc).  The stream is chosen by the machine: MSX1 / MSX2 (the picture coded for the
; palette of the film), PSG / SCC.  Out: carry = SPACE, RETURN or the fire button stopped it.  (SCC: scc_tvstart before, scc_off after, in the code bank.)
ov_fony:di
        IF SCC
        ld a,(v_sccm)
        or a
        jr nz,.scc
        ENDIF
        ld hl,FYP1
        IF MSX2PAL
        ld a,(v_msx)
        or a
        jr z,.p
        ld hl,FYP2
.p:
        ENDIF
        ld (fy_base),hl
        ld a,(v_tvd)
        or a
        jp nz,w_fony
        jp fony
        IF SCC
.scc:   ld hl,FYS1
        IF MSX2PAL
        ld a,(v_msx)
        or a
        jr z,.s
        ld hl,FYS2
.s:
        ENDIF
        ld (fy_base),hl
        ld a,(v_tvd)
        or a
        jp nz,w_fony16
        jp fony16
        ENDIF
        INCLUDE "fony.inc"
        INCLUDE "fonyw.inc"
        IF SCC
        INCLUDE "fony16.inc"
        INCLUDE "fony16w.inc"
        ENDIF
        INCLUDE "fonytab.inc"
